"""一次性离线核验 v60；不构建、不重跑 LP。"""
import collections, copy, datetime, gzip, hashlib, json, math, re, statistics, subprocess, sys, zipfile
from pathlib import Path
sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "knowledge/experiments/data/2026-10-12-halpern-ipm"
PLAN_SHA = "14449d41223536674262fc242f04c2d0dac1236ad150fea1317c310eaeecdfc2"
FIELDS = ("ipm_extended_krylov_attempts", "ipm_extended_krylov_successes")
COMPAT = ("compatibility-development", "compatibility-probe")
STAGES = (*COMPAT, "development", "probe", "netlib", "highs")
ALLOWED = {"optimal": (0, "resolved"), "empty": (0, "resolved"), "infeasible": (0, "resolved"),
    "unbounded": (0, "resolved"), "verification_failed": (3, "verification_failed"),
    "time_limit": (4, "incomplete"), "iteration_limit": (4, "incomplete"), "numerical_error": (4, "incomplete")}

def require(condition, message):
    if not condition:
        raise AssertionError(message)

def strict(text):
    def pairs(values):
        result = {}
        for key, value in values:
            require(key not in result, "JSON 重复键")
            result[key] = value
        return result
    def number(text):
        value = float(text)
        require(math.isfinite(value), "JSON 非有限浮点")
        return value
    def invalid(text):
        raise ValueError("JSON 非有限常量：" + text)
    return json.loads(text, object_pairs_hook=pairs, parse_float=number, parse_constant=invalid)

def read(path):
    return strict(Path(path).read_text(encoding="utf-8"))

def sha(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

def finite(value):
    return type(value) in (int, float) and math.isfinite(value)

def same(a, b):
    if type(a) is bool or type(b) is bool:
        return type(a) is type(b) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[key], b[key]) for key in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def flags(arguments):
    require(len(arguments) % 2 == 0, "参数必须成对")
    result = dict(zip(arguments[::2], arguments[1::2]))
    require(len(result) * 2 == len(arguments) and all(key.startswith("--") for key in result), "重复或非法参数")
    return result

def valid_counts(report, version, backend, mode):
    present = [key in report for key in FIELDS]
    if version == 57 and not any(present):
        return True
    if not all(present):
        return False
    a, s = (report[key] for key in FIELDS)
    if backend != "ipm":
        return a is None and s is None
    return type(a) is int and type(s) is int and 0 <= s <= a <= 9223372036854775807 and (mode == "homogeneous_extended" or a == s == 0)

def valid_process(row):
    report = row.get("report")
    if row.get("error") is not None or not isinstance(report, dict) or type(row.get("returncode")) is not int:
        return False
    if type(report.get("schema_version")) is not int or report["schema_version"] != 1:
        return False
    status = report.get("status")
    if not isinstance(status, str) or status not in ALLOWED or row.get("status") != status:
        return False
    if (row["returncode"], row.get("classification")) != ALLOWED[status]:
        return False
    times = report.get("timings")
    if not isinstance(times, dict) or not all(finite(times.get(key)) and times[key] >= 0 for key in ("read_seconds", "solve_seconds", "verification_seconds", "total_seconds")):
        return False
    return finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"] > 0 and finite(row.get("numerical_seconds")) and row["numerical_seconds"] >= 0

def limited(row):
    return row.get("error") == "wall_timeout" or (row.get("report") or {}).get("status") == "time_limit" or (finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"] > 35) or (finite(row.get("numerical_seconds")) and row["numerical_seconds"] > 5)

def trajectory(a, b):
    reports = copy.deepcopy([a.get("report"), b.get("report")])
    for report in reports:
        if isinstance(report, dict):
            for key in ("timings", "backend_version", *FIELDS):
                report.pop(key, None)
    equal = same(*reports) and a.get("returncode") == b.get("returncode") and a.get("error") == b.get("error")
    valid, budget = valid_process(a) and valid_process(b), limited(a) or limited(b)
    return {"equal": equal, "valid_processes": valid, "budget_limited": budget,
        "category": "invalid_process" if not valid else "budget_limited" if budget else "equal" if equal else "different"}

def self_check():
    cases = [({}, 57, "ipm", "homogeneous_repair", True), ({}, 60, "ipm", "homogeneous_extended", False)]
    for values, mode, good in (((0, 0), "homogeneous_repair", True), ((1, 0), "homogeneous_repair", False), ((1, 1), "homogeneous_extended", True), ((1, 2), "homogeneous_extended", False), ((True, 0), "homogeneous_extended", False), ((1, False), "homogeneous_extended", False), ((-1, 0), "homogeneous_extended", False), ((1.0, 0), "homogeneous_extended", False), ((9223372036854775808, 0), "homogeneous_extended", False)):
        cases.append((dict(zip(FIELDS, values)), 60, "ipm", mode, good))
    cases += [(dict.fromkeys(FIELDS, None), 60, "highs", "homogeneous_extended", True), ({FIELDS[0]: 0}, 57, "ipm", "homogeneous_repair", False)]
    for report, version, backend, mode, good in cases:
        require(valid_counts(report, version, backend, mode) is good, "计数反例")
    row = {"error": None, "classification": "incomplete", "status": "numerical_error", "returncode": 4,
        "report": {"schema_version": 1, "status": "numerical_error", "backend_version": "ipm-cpu-0.47.0", "timings": {"read_seconds": 0, "solve_seconds": 1, "verification_seconds": 0, "total_seconds": 1}}, "numerical_seconds": 1, "elapsed_wall_seconds": 2}
    modern = copy.deepcopy(row)
    modern["report"].update(backend_version="ipm-cpu-0.49.0", **dict.fromkeys(FIELDS, 0))
    require(trajectory(row, modern)["category"] == "equal", "兼容排除字段")
    budget = copy.deepcopy(row)
    budget["status"] = budget["report"]["status"] = "time_limit"
    require(trajectory(row, budget)["category"] == "budget_limited", "合法预算分叉")
    invalids = []
    for status in ("bogus", None, True):
        bad = copy.deepcopy(row)
        bad["status"] = bad["report"]["status"] = status
        invalids.append(bad)
    for key, value in (("returncode", False), ("returncode", -1073741819), ("error", "wall_timeout"), ("numerical_seconds", None)):
        bad = copy.deepcopy(row)
        bad[key] = value
        invalids.append(bad)
    for bad in invalids:
        require(trajectory(bad, budget)["category"] == "invalid_process", "invalid 必须优先于预算")
    require(not same({"x": True}, {"x": 1}), "布尔不得冒充整数")
    try:
        strict('{"x":1,"x":2}')
    except AssertionError:
        pass
    else:
        raise AssertionError("重复 JSON 键未拒绝")
    return {"passed": True, "count_cases": len(cases), "trajectory_cases": 2 + len(invalids), "invalid_budget_counterexamples": len(invalids), "json_and_type_cases": 2, "lp_runs": 0}

def expected_options(backend, mode):
    return {"backend": backend, "time_limit": 5, "threads": 1, "seed": 0, "mip_relative_gap": 0.0001, "pdlp": None,
        "ipm": None if backend == "highs" else {"method": "homogeneous", "max_iterations": 200, "scaling_passes": 5, "objective_scaling": False, "eliminate_singletons": True, "dynamic_regularization": False, "equilibrate_kkt": True, "linear_accuracy": mode, "central_corrections": 0, "direction_retries": 0, "krylov_history_size": 0, "linear_solver": "normal_cholmod", "eliminate_fixed_variables": True, "presolve_singleton_rows": False, "eliminate_presolved_fixed_variables": False, "inexact_prefilter": False},
        "highs": {"solver": "choose", "run_crossover": "on", "presolve": "choose"} if backend == "highs" else None,
        "tolerances": {"feasibility_absolute": 1e-7, "feasibility_relative": 1e-9, "integrality": 1e-6, "objective_absolute": 1e-7, "objective_relative": 1e-9}}

def numerical_flags(backend, mode):
    result = {"--backend": backend, "--time-limit": "5.0", "--threads": "1", "--seed": "0", "--mip-gap": "0.0001"}
    if backend == "highs":
        result.update({"--highs-solver": "choose", "--highs-crossover": "on", "--highs-presolve": "choose"})
    else:
        result.update({"--iteration-limit": "200", "--scaling-passes": "5", "--ipm-method": "homogeneous", "--ipm-linear-accuracy": mode, "--ipm-linear-solver": "normal_cholmod", "--ipm-direction-retries": "0", "--ipm-objective-scaling": "off", "--ipm-singleton-elimination": "on", "--ipm-dynamic-regularization": "off", "--ipm-kkt-equilibration": "on", "--ipm-fixed-variable-elimination": "on", "--ipm-singleton-presolve": "off", "--ipm-presolve-fixed-elimination": "off", "--ipm-krylov-history-size": "0", "--ipm-central-corrections": "0", "--ipm-inexact-prefilter": "off"})
    return result

def sgm(values):
    return math.expm1(sum(math.log1p(value / 10.0) for value in values) / len(values)) * 10.0

def audit_summary(summary, rows, models, repeats, sides):
    require(summary["model_count"] == len(models) and summary["repeats"] == repeats and summary["run_count"] == len(rows), "汇总数量")
    require(summary["quality_pass_count"] == sum(row["quality_pass"] for row in rows), "总达标数")
    result = {}
    for side in sides:
        selected = [row for row in rows if row["requested_variant"] == side]
        counts = collections.Counter(row["model_index"] for row in selected if row["quality_pass"])
        expected = {"run_count": len(selected), "quality_pass_count": sum(row["quality_pass"] for row in selected),
            "all_repeats_quality_pass_model_count": sum(counts[model["model_index"]] == repeats for model in models),
            "quality_failure_counts": dict(collections.Counter(row["quality_failure"] for row in selected if not row["quality_pass"])),
            "status_counts": dict(collections.Counter(row["status"] for row in selected)),
            "penalized_wall_sgm10_seconds": sgm([row["quality_penalized_wall_seconds"] for row in selected]),
            "penalized_numerical_sgm10_seconds": sgm([row["quality_penalized_numerical_seconds"] for row in selected]),
            "numerical_budget_exceeded_count": sum(row["numerical_budget_exceeded"] for row in selected),
            "wall_budget_exceeded_count": sum(row["wall_budget_exceeded"] for row in selected)}
        require(same(summary["variants"][side], expected), "独立重算每侧 SGM/覆盖/状态")
        result[side] = expected
    require(len(summary["models"]) == len(models), "逐例汇总数量")
    both, winners = 0, collections.Counter()
    for model, item in zip(models, summary["models"]):
        groups = {side: [row for row in rows if row["requested_variant"] == side and row["model_index"] == model["model_index"]] for side in sides}
        require(all(len(group) == repeats for group in groups.values()), "逐例重复次数")
        counts = {side: sum(row["quality_pass"] for row in group) for side, group in groups.items()}
        require((item["input"], item["sha256"], item["model_index"]) == (model["input"], model["sha256"], model["model_index"]), "逐例身份")
        require(item["quality_pass_counts"] == counts, "逐例达标次数")
        complete = all(value == repeats for value in counts.values())
        require(item["all_repeats_quality_pass"] is complete, "双方完整达标标志")
        if complete:
            both += 1
            for kind, field in (("wall", "elapsed_wall_seconds"), ("numerical", "numerical_seconds")):
                median = {side: statistics.median(row[field] for row in group) for side, group in groups.items()}
                ranges = {side: [min(row[field] for row in group), max(row[field] for row in group)] for side, group in groups.items()}
                require(item["median_" + kind + "_seconds"] == median and item[kind + "_range_seconds"] == ranges, "逐例中位数/区间")
                ratio = median[sides[0]] / median[sides[1]] if median[sides[1]] > 0 else None
                require(item[kind + "_speedup_reference_over_candidate"] == ratio, "逐例速度比")
                if kind == "wall":
                    winner = "tie" if median[sides[0]] == median[sides[1]] else min(median, key=median.get)
                    require(item["wall_winner"] == winner, "逐例墙钟胜者")
                    winners[winner] += 1
        else:
            require(all(item[key] is None for key in ("median_wall_seconds", "median_numerical_seconds", "wall_range_seconds", "numerical_range_seconds", "wall_speedup_reference_over_candidate", "numerical_speedup_reference_over_candidate", "wall_winner")), "失败样本不得计算成功速度")
    require(summary["both_variants_all_repeats_pass_count"] == both and summary["wall_winner_counts"] == dict(winners), "整体成对统计")
    return result

def main():
    checks = self_check()
    if "--self-check" in sys.argv:
        print(json.dumps(checks, ensure_ascii=False))
        return
    plan = read(DATA / "v60-plan.json")
    require(sha(DATA / "v60-plan.json") == PLAN_SHA, "固定计划")
    require(sha(DATA / "ipm-v57-identity.json") == plan["parent_identity_sha256"] and sha(DATA / plan["evidence_file"]) == plan["evidence_sha256"], "父版和诊断证据身份")
    old_plan = read(DATA / "v57-plan.json")
    require(plan["sets"] == old_plan["sets"] and plan["shared_ipm"] == old_plan["shared_ipm"] and plan["highs_reference"] == old_plan["highs_reference"], "既定输入和数值政策不变")
    require((plan["compatibility_runs"], plan["initial_performance_runs"], plan["conditional_full_performance_runs"], plan["maximum_solver_runs"]) == (34, 102, 364, 500), "数量合同")
    ids = {version: read(DATA / f"ipm-v{version}-identity.json") for version in (57, 60)}
    parent, current = ids[57], ids[60]
    require(current["plan_sha256"] == PLAN_SHA and datetime.datetime.fromisoformat(current["created_at_utc"]) >= datetime.datetime.fromisoformat(plan["created_at_utc"]), "先计划后冻结")
    snapshots = {}
    for version, identity in ids.items():
        require(sha(ROOT / f".tools/solver-ipm-v{version}.exe") == identity["solver_sha256"], "冻结程序身份")
        path = DATA / f"ipm-v{version}-source.zip"
        require(sha(path) == identity["source_zip_sha256"], "源码包身份")
        with zipfile.ZipFile(path) as archive:
            names = archive.namelist()
            require(len(names) == len(set(names)) == 95 and set(names) == set(identity["files"]), "95唯一来源成员")
            snapshots[version] = {name: archive.read(name) for name in names}
        require({name: hashlib.sha256(content).hexdigest() for name, content in snapshots[version].items()} == identity["files"], "每个源码成员身份")
    require(set(current["files"]) == set(parent["files"]), "来源集合未变")
    changed = sorted(name for name in current["files"] if current["files"][name] != parent["files"][name])
    require(len(changed) == 10 and changed == sorted(plan["changed_source_files"]) == current["changed_source_files"], "恰10来源变化")
    require({name: sha(ROOT / name) for name in current["files"]} == current["files"], "当前95来源")
    require(sha(ROOT / "build/release/solver.exe") == current["solver_sha256"] != parent["solver_sha256"], "当前实际新程序")
    require(current["compiler"] == parent["compiler"] and sha(current["compiler"]) == current["compiler_sha256"] == parent["compiler_sha256"], "同编译器")
    require(len(current["libraries"]) == 17 and set(current["libraries"]) == set(parent["libraries"]), "17库集合")
    require({name: sha(ROOT / name) for name in current["libraries"]} == current["libraries"], "当前17实际库")
    changed_libraries = sorted(name for name in current["libraries"] if current["libraries"][name] != parent["libraries"][name])
    require(changed_libraries == current["changed_libraries"] and "build/release/libsolver_ipm.a" in changed_libraries, "实际变化库记录")
    external = [name for name in current["libraries"] if not Path(name).name.startswith("libsolver_")]
    require(len(external) == 8 and not set(external).intersection(changed_libraries), "8第三方库完全相同")
    commands = subprocess.check_output([str(ROOT / ".tools/ninja-1.13.2/ninja.exe"), "-C", str(ROOT / "build/release"), "-t", "commands", "solver.exe"], text=True, encoding="utf-8").splitlines()
    links = [line for line in commands if " -o solver.exe " in line]
    require(links == [current["link_command"]], "当前真实链接命令")
    libraries = [quoted or plain for quoted, plain in re.findall(r'"([^"\n]+\.a)"|([^\s";]+\.a)(?=\s|$)', links[0]) if not (quoted or plain).startswith("-")]
    require({(ROOT / "build/release" / name).resolve() for name in libraries} == {(ROOT / name).resolve() for name in current["libraries"]}, "真实链接17库输入")
    patch, = strict(snapshots[60]["dependencies.lock.json"])["openblas"]["local_patches"]
    require(current["files"][patch["path"]] == patch["sha256"] and sha(ROOT / "build/openblas/openblas-0.3.33/src/solver_openblas_build" / patch["source_file"]) == current["patched_openblas_source_sha256"] == parent["patched_openblas_source_sha256"] == patch["patched_sha256"], "BLAS修补身份")
    for filename, key in (("v60-run.py", "runner_sha256"), ("v60-freeze.py", "freeze_script_sha256"), ("v60-runner-self-check.json", "runner_self_check_sha256")):
        require(sha(DATA / filename) == current[key], "冻结工具身份")
    require({name: sha(DATA / name) for name in current["logs"]} == current["logs"], "正式测试日志身份")
    require("100% tests passed out of 18" in (DATA / "iteration-ipm-v60-build.log").read_text(encoding="utf-8"), "正式18测试通过")
    require((DATA / "iteration-ipm-v60-ctest-detail.log").read_text(encoding="utf-8").count("Test Passed.") == 18, "逐项18测试")
    input_hashes = {}
    for name, count, repeats in (("development", 11, 3), ("probe", 6, 3), ("netlib", 91, 1)):
        group = plan["sets"][name]
        source = Path(group["models_file"])
        require(group["repeats"] == repeats and sha(source) == group["models_file_sha256"], "冻结列表")
        paths = [str((source.parent / line.strip()).resolve()) for line in source.read_text(encoding="utf-8-sig").splitlines() if line.strip()]
        require(len(set(paths)) == len(paths) == count and paths == [model["input"] for model in group["models"]], "列表内容和数量")
        require([model["model_index"] for model in group["models"]] == list(range(count)), "冻结模型顺序")
        for model in group["models"]:
            if model["input"] not in input_hashes:
                input_hashes[model["input"]] = sha(model["input"])
            require(model["hash_error"] is None and input_hashes[model["input"]] == model["sha256"], "当前模型身份")
    sys.path.insert(0, str(ROOT / "scripts"))
    import benchmark
    import compare_lp
    require(sha(benchmark.__file__) == current["files"]["scripts/benchmark.py"] and sha(compare_lp.__file__) == current["files"]["scripts/compare_lp.py"], "复用质量函数冻结身份")
    audited, groups = {}, {}

    def audit_stage(stage):
        group = plan["sets"]["netlib" if stage in ("netlib", "highs") else stage.removeprefix("compatibility-")]
        models = group["models"]
        repeats = 1 if stage in COMPAT else group["repeats"]
        prefix = "v60-" + stage + "-"
        manifest, summary, process = (read(DATA / (prefix + name + ".json")) for name in ("manifest", "summary", "process"))
        content = gzip.decompress((DATA / (prefix + "runs.jsonl.gz")).read_bytes())
        rows = [strict(line) for line in content.splitlines()]
        output = ROOT / ("results/round-ipm-v60-" + stage)
        require((output / "runs.jsonl").read_bytes() == content and read(output / "manifest.json") == manifest and read(output / "summary.json") == summary, "原始与归档证据相同")
        require(len(rows) == len(models) * repeats * 2 and manifest["models"] == models and manifest["models_file_sha256"] == group["models_file_sha256"], "阶段数量/输入")
        require((manifest["repeats"], manifest["time_limit"], manifest["wall_timeout"], manifest["threads"], manifest["seed"]) == (repeats, 5, 35, 1, 0), "共同预算")
        sides = (manifest["reference_variant"], manifest["candidate_variant"])
        require(len(set(sides)) == 2 and summary["reference_variant"] == sides[0] and summary["candidate_variant"] == sides[1], "独立两侧")
        require(summary["configurations"] == manifest["variants"] and summary["output_dir"] == str(output), "汇总配置来源")
        script_hashes = {str(ROOT / "scripts" / name): current["files"]["scripts/" + name] for name in ("benchmark.py", "compare_lp.py")}
        require(process["protected_scripts"] == script_hashes and process["plan_sha256"] == PLAN_SHA, "执行时脚本身份")
        require(process["environment"] == {name: "1" for name in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS")}, "单线程环境")
        require(process["removed_environment"] == ["OPENBLAS_CORETYPE", "所有SOLVER_V前缀变量"], "移除旧诊断环境")
        require(process["solver_sha256_after"] == current["solver_sha256"] and process["reference_solver_sha256_after"] == ids[60 if stage == "highs" else 57]["solver_sha256"], "运行结束程序身份")
        require(manifest["comparison_script_sha256"] == current["files"]["scripts/compare_lp.py"] and manifest["benchmark_script_sha256"] == current["files"]["scripts/benchmark.py"], "实际运行器身份")
        driver = read(DATA / (prefix + "command.json"))
        require(driver[:2] == [sys.executable, str(ROOT / "scripts/compare_lp.py")], "实际驱动命令")
        base = {"--solver": str(ROOT / ".tools/solver-ipm-v60.exe"), "--reference-solver": str(ROOT / f".tools/solver-ipm-v{60 if stage == 'highs' else 57}.exe"),
            "--models-file": group["models_file"], "--repeats": str(repeats), "--time-limit": "5", "--wall-timeout": "35", "--threads": "1", "--seed": "0",
            "--candidate-backend": "ipm", "--reference-backend": "highs" if stage == "highs" else "ipm", "--output-dir": str(output)}
        for side, prefix_flag in (("reference", "--reference-"), ("candidate", "--")):
            backend = "highs" if side == "reference" and stage == "highs" else "ipm"
            mode = "homogeneous_repair" if side == "reference" or stage in COMPAT else "homogeneous_extended"
            for key, value in numerical_flags(backend, mode).items():
                if key not in ("--backend", "--time-limit", "--threads", "--seed", "--mip-gap"):
                    base[prefix_flag + key[2:]] = value
        require(flags(driver[2:]) == base, "完整事前驱动参数")
        index, details = 0, []
        for model in models:
            for repeat in range(repeats):
                order = sides if (model["model_index"] + repeat) % 2 == 0 else sides[::-1]
                for position, variant in enumerate(order):
                    row = rows[index]
                    side = "reference" if variant == sides[0] else "candidate"
                    backend = "highs" if side == "reference" and stage == "highs" else "ipm"
                    version = 57 if side == "reference" and stage != "highs" else 60
                    mode = "homogeneous_repair" if side == "reference" or stage in COMPAT else "homogeneous_extended"
                    solver = manifest["solvers"][variant]
                    expected_solver = str(ROOT / f".tools/solver-ipm-v{version}.exe")
                    require(solver == {"path": expected_solver, "sha256": ids[version]["solver_sha256"], "hash_error": None}, "variant真实程序")
                    require(all(type(row.get(key)) is int for key in ("run_index", "model_index", "repetition", "position_in_pair", "seed")), "运行序号严格整数")
                    require((row["run_index"], row["model_index"], row["repetition"], row["position_in_pair"], row["seed"]) == (index, model["model_index"], repeat, position, 0), "实际交替运行顺序")
                    require((row["input"], row["requested_variant"], row["requested_backend"]) == (model["input"], variant, backend), "运行配置身份")
                    require(all(row[field] == model["sha256"] for field in ("model_sha256", "model_sha256_after", "frozen_model_sha256")) and row["hash_error"] is None, "输入前后身份")
                    require(all(row[field] == ids[version]["solver_sha256"] for field in ("solver_sha256_before", "solver_sha256_after", "frozen_solver_sha256")), "程序前后身份")
                    require(valid_process(row), "非法状态/退出/报告，不能以预算掩盖：" + stage + ":" + str(index))
                    report = row["report"]
                    require(same(strict(row["stdout"]), report), "原始stdout与解析报告")
                    require(report["input"] == model["input"] and report["backend"] == backend, "实际报告输入后端")
                    require(report["backend_version"] == ("1.15.1" if backend == "highs" else "ipm-cpu-0.47.0" if version == 57 else "ipm-cpu-0.49.0"), "实际版本")
                    require(same(report["options"], expected_options(backend, mode)), "完整实际选项与原容差")
                    require(valid_counts(report, version, backend, mode), "扩展Krylov计数合同")
                    require(row["command"][:3] == [expected_solver, "solve", model["input"]] and flags(row["command"][3:]) == numerical_flags(backend, mode), "实际子进程参数")
                    numerical = report["timings"]["solve_seconds"] + report["timings"]["verification_seconds"]
                    require(row["numerical_seconds"] == numerical and finite(numerical), "数值时间重新计算")
                    require(benchmark.classify(row["returncode"], report) == row["classification"], "冻结质量分类一致")
                    failure = compare_lp.quality_failure(row, model, model["sha256"], ids[version]["solver_sha256"], ids[version]["solver_sha256"])
                    wall_over, numeric_over = row["elapsed_wall_seconds"] > 35, numerical > 5
                    if failure is None and wall_over:
                        failure = "wall_budget_exceeded"
                    if failure is None and numeric_over:
                        failure = "numerical_budget_exceeded"
                    require(row["quality_failure"] == failure and row["quality_pass"] is (failure is None), "逐例质量/预算")
                    require(row["wall_budget_exceeded"] is wall_over and row["numerical_budget_exceeded"] is numeric_over, "预算标志")
                    require(row["quality_penalized_wall_seconds"] == (min(row["elapsed_wall_seconds"], 35) if failure is None else 35), "墙钟失败罚分")
                    require(row["quality_penalized_numerical_seconds"] == (min(numerical, 5) if failure is None else 5), "数值失败罚分")
                    if version == 60 and backend == "ipm" and report[FIELDS[0]]:
                        details.append({"input": model["input"], "repetition": repeat, "status": report["status"], "quality_pass": row["quality_pass"],
                            "numerical_seconds": numerical, "wall_seconds": row["elapsed_wall_seconds"], **{key: report[key] for key in FIELDS}})
                    index += 1
        require(type(process["returncode"]) is int and process["returncode"] == (0 if all(row["quality_pass"] for row in rows) else 1), "驱动实际退出码")
        variants = audit_summary(summary, rows, models, repeats, sides)
        groups[stage] = (manifest, summary, rows)
        audited[stage] = {"runs": len(rows), "raw_sha256": sha(DATA / ("v60-" + stage + "-runs.jsonl.gz")), "variants": variants, "extended_triggered_records": details}

    for stage in COMPAT:
        audit_stage(stage)
    pairs = []
    for stage in COMPAT:
        manifest, _, rows = groups[stage]
        for model in manifest["models"]:
            selected = {row["requested_variant"]: row for row in rows if row["model_index"] == model["model_index"]}
            a, b = (selected[manifest[side + "_variant"]] for side in ("reference", "candidate"))
            pairs.append({"stage": stage, "input": model["input"], **trajectory(a, b)})
    require(len(pairs) == 17, "17完整兼容对子")
    compat = {"passed": all(item["category"] == "equal" for item in pairs), "runs": 34, "pairs": pairs,
        "non_budget_equal": sum(item["category"] == "equal" for item in pairs), "budget_pairs": sum(item["category"] == "budget_limited" for item in pairs),
        "invalid_pairs": sum(item["category"] == "invalid_process" for item in pairs), "different_pairs": sum(item["category"] == "different" for item in pairs), "plan_sha256": PLAN_SHA}
    require(same(read(DATA / "v60-compatibility.json"), compat), "独立17对子与保存合同一致")
    gate = None
    if compat["passed"]:
        for stage in ("development", "probe"):
            audit_stage(stage)
        def deltas(stage):
            manifest, _, rows = groups[stage]
            sides = (manifest["reference_variant"], manifest["candidate_variant"])
            counts = {model["input"]: [sum(row["quality_pass"] for row in rows if row["input"] == model["input"] and row["requested_variant"] == side) for side in sides] for model in manifest["models"]}
            return ([Path(name).stem for name, pair in counts.items() if pair[1] < pair[0]], [Path(name).stem for name, pair in counts.items() if pair[1] > pair[0]])
        dev_lost, _ = deltas("development")
        probe_lost, probe_gain = deltas("probe")
        manifest, _, rows = groups["development"]
        measured = {side: {kind: sgm([row["quality_penalized_" + kind + "_seconds"] for row in rows if row["requested_variant"] == manifest[side + "_variant"]]) for kind in ("numerical", "wall")} for side in ("reference", "candidate")}
        speed = measured["candidate"]["numerical"] < measured["reference"]["numerical"] and measured["candidate"]["wall"] <= measured["reference"]["wall"]
        gate = {"development_lost": dev_lost, "probe_lost": probe_lost, "probe_gain": probe_gain, "development_speed_gate": speed,
            "eligible_for_netlib": not dev_lost and not probe_lost and (speed or bool(probe_gain)), "plan_sha256": PLAN_SHA}
        require(same(gate, read(DATA / "v60-gate.json")), "独立逐例覆盖及SGM门槛")
        if gate["eligible_for_netlib"]:
            for stage in ("netlib", "highs"):
                audit_stage(stage)
    for stage in set(STAGES) - set(groups):
        require(not list(DATA.glob("v60-" + stage + "-*")) and not (ROOT / ("results/round-ipm-v60-" + stage)).exists(), "门槛未通过禁止额外阶段：" + stage)
    runs = sum(item["runs"] for item in audited.values())
    require(runs == (500 if gate and gate["eligible_for_netlib"] else 136 if compat["passed"] else 34), "保留全部事前运行数量")
    result = {"passed": True, "created_at_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(), "plan_sha256": PLAN_SHA,
        "temporary_verifier_sha256": sha(__file__), "identity_sha256": sha(DATA / "ipm-v60-identity.json"),
        "source_files": 95, "changed_source_files": changed, "actual_linked_libraries": 17, "changed_libraries": changed_libraries,
        "unchanged_third_party_libraries": 8, "ctest_passed": 18, "run_count": runs, "compatibility_runs": 34, "performance_runs": runs - 34,
        "compatibility": compat, "gate": gate, "stages": audited, "self_check": checks,
        "reused_quality_functions": {"benchmark_sha256": current["files"]["scripts/benchmark.py"], "compare_lp_sha256": current["files"]["scripts/compare_lp.py"]},
        "limits": ["独立检查身份、状态、计数、实际参数、报告轨迹、SGM和扩集合同；不构建或重跑LP。",
            "原模型质量复核复用已冻结的LP质量纯函数及求解器验收报告，不是第二次数值求解或独立读取矩阵验模。",
            "核验真实显式17库链接输入；未逐项核验链接器隐式运行库。", "passed表示证据合同通过，不表示打平HiGHS。"], "lp_runs_by_verifier": 0}
    with (DATA / "v60-verification.json").open("x", encoding="utf-8") as target:
        json.dump(result, target, ensure_ascii=False, indent=2, allow_nan=False)
        target.write("\n")
    print(json.dumps({"passed": True, "run_count": runs, "compatibility_equal": compat["non_budget_equal"], "gate": gate}, ensure_ascii=False))

if __name__ == "__main__":
    main()
